"use client";

import { useState } from "react";
import { 
  Calendar, Clock, CheckCircle, 
  AlertCircle, MoreVertical, Plus, 
  Filter, TrendingUp, Target, Flag
} from "lucide-react";

// DATA DUMMY PROKER
const initialProkers = [
  { 
    id: 1, title: "Classmeeting Semester Ganjil", division: "Sekbid 4 (Olah Raga)", 
    date: "2026-01-15", status: "ongoing", progress: 65, 
    budget: 5000000, pic: "Dimas Anggara" 
  },
  { 
    id: 2, title: "Latihan Dasar Kepemimpinan (LDKS)", division: "Inti & MPK", 
    date: "2026-02-10", status: "planned", progress: 20, 
    budget: 12000000, pic: "Raka Aditya" 
  },
  { 
    id: 3, title: "Peringatan Isra Mi'raj", division: "Sekbid 1 (Agama)", 
    date: "2026-01-28", status: "ongoing", progress: 80, 
    budget: 3500000, pic: "Siti Aminah" 
  },
  { 
    id: 4, title: "Donor Darah Rutin", division: "Sekbid 7 (Kesehatan)", 
    date: "2025-12-20", status: "completed", progress: 100, 
    budget: 500000, pic: "Nadina Putri" 
  },
  { 
    id: 5, title: "Mading Sekolah Edisi Baru", division: "Sekbid 9 (TIK)", 
    date: "2026-01-05", status: "completed", progress: 100, 
    budget: 200000, pic: "Seksi Pubdok" 
  },
];

export default function ProkerPage() {
  const [prokers, setProkers] = useState(initialProkers);
  const [filter, setFilter] = useState('all');

  // Logic H-Hari
  const getDaysLeft = (dateStr: string) => {
    const today = new Date();
    const eventDate = new Date(dateStr);
    const diffTime = eventDate.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    
    if (diffDays < 0) return "Selesai";
    if (diffDays === 0) return "Hari H";
    return `H-${diffDays}`;
  };

  // Helper Warna Status
  const getStatusColor = (status: string) => {
    switch(status) {
      case 'planned': return 'bg-slate-100 text-slate-600 dark:bg-white/10 dark:text-slate-300';
      case 'ongoing': return 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400';
      case 'completed': return 'bg-green-100 text-green-600 dark:bg-green-900/30 dark:text-green-400';
      default: return 'bg-slate-100 text-slate-600';
    }
  };

  const getStatusLabel = (status: string) => {
    switch(status) {
      case 'planned': return 'Rencana';
      case 'ongoing': return 'Berjalan';
      case 'completed': return 'Selesai';
      default: return '-';
    }
  };

  const filteredProkers = filter === 'all' ? prokers : prokers.filter(p => p.status === filter);

  return (
    <div className="h-[calc(100vh-6rem)] flex flex-col gap-6 font-sans">
      
      {/* === HEADER STATS === */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 shrink-0">
         <div className="bg-blue-600 p-5 rounded-2xl text-white relative overflow-hidden shadow-lg shadow-blue-600/20">
            <div className="absolute right-0 top-0 opacity-10 p-4"><Target size={64}/></div>
            <p className="text-xs font-bold opacity-80 uppercase tracking-wider mb-1">Total Proker</p>
            <h2 className="text-3xl font-black">{prokers.length} <span className="text-sm font-medium opacity-60">Program</span></h2>
         </div>
         <div className="bg-white dark:bg-[#0f172a] p-5 rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm">
            <div className="flex items-center gap-3 mb-2"><div className="p-2 bg-blue-100 dark:bg-blue-900/20 text-blue-600 rounded-lg"><TrendingUp size={18}/></div><p className="text-xs font-bold text-slate-500 uppercase">Sedang Berjalan</p></div>
            <h2 className="text-2xl font-black text-slate-800 dark:text-white">{prokers.filter(p => p.status === 'ongoing').length}</h2>
         </div>
         <div className="bg-white dark:bg-[#0f172a] p-5 rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm">
            <div className="flex items-center gap-3 mb-2"><div className="p-2 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 rounded-lg"><Calendar size={18}/></div><p className="text-xs font-bold text-slate-500 uppercase">Rencana</p></div>
            <h2 className="text-2xl font-black text-slate-800 dark:text-white">{prokers.filter(p => p.status === 'planned').length}</h2>
         </div>
         <div className="bg-white dark:bg-[#0f172a] p-5 rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm">
            <div className="flex items-center gap-3 mb-2"><div className="p-2 bg-green-100 dark:bg-green-900/20 text-green-600 rounded-lg"><CheckCircle size={18}/></div><p className="text-xs font-bold text-slate-500 uppercase">Selesai</p></div>
            <h2 className="text-2xl font-black text-slate-800 dark:text-white">{prokers.filter(p => p.status === 'completed').length}</h2>
         </div>
      </div>

      {/* === MAIN CONTENT === */}
      <div className="flex-1 bg-white dark:bg-[#0f172a] rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm flex flex-col overflow-hidden">
         
         {/* Toolbar */}
         <div className="p-5 border-b border-slate-100 dark:border-white/5 flex flex-col md:flex-row justify-between items-center gap-4 bg-slate-50/50 dark:bg-white/5">
            <div className="flex bg-white dark:bg-[#1e293b] rounded-xl border border-slate-200 dark:border-white/10 p-1 shadow-sm">
                {['all', 'planned', 'ongoing', 'completed'].map(status => (
                    <button key={status} onClick={() => setFilter(status)} className={`px-4 py-1.5 rounded-lg text-[10px] font-bold capitalize transition-all ${filter === status ? 'bg-slate-100 dark:bg-white/20 text-slate-900 dark:text-white shadow-sm' : 'text-slate-500 hover:text-slate-800 dark:hover:text-slate-300'}`}>
                        {status === 'all' ? 'Semua' : status === 'planned' ? 'Rencana' : status === 'ongoing' ? 'Berjalan' : 'Selesai'}
                    </button>
                ))}
            </div>
            <button className="px-5 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold text-xs shadow-lg shadow-blue-600/20 active:scale-95 transition-all flex items-center gap-2">
               <Plus size={16}/> Buat Proker Baru
            </button>
         </div>

         {/* GRID PROKER */}
         <div className="flex-1 overflow-y-auto custom-scrollbar p-6">
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
               {filteredProkers.map((proker) => (
                  <div key={proker.id} className="bg-white dark:bg-[#1e293b] border border-slate-100 dark:border-white/5 rounded-2xl p-5 shadow-sm hover:shadow-lg hover:-translate-y-1 transition-all duration-300 group flex flex-col justify-between h-full relative overflow-hidden">
                     
                     {/* Decorative Line */}
                     <div className={`absolute top-0 left-0 w-full h-1 ${
                        proker.status === 'ongoing' ? 'bg-blue-500' : 
                        proker.status === 'completed' ? 'bg-green-500' : 'bg-slate-300'
                     }`}></div>

                     <div>
                        {/* Header Card */}
                        <div className="flex justify-between items-start mb-3">
                           <span className={`px-2.5 py-1 rounded-md text-[10px] font-bold uppercase tracking-wider ${getStatusColor(proker.status)}`}>
                              {getStatusLabel(proker.status)}
                           </span>
                           {proker.status !== 'completed' && (
                              <span className={`px-2.5 py-1 rounded-md text-[10px] font-black ${getDaysLeft(proker.date).includes('Selesai') ? 'text-slate-400 bg-slate-100' : 'text-red-600 bg-red-100 dark:bg-red-900/30 animate-pulse'}`}>
                                 {getDaysLeft(proker.date)}
                              </span>
                           )}
                        </div>

                        {/* Content */}
                        <h3 className="text-lg font-black text-slate-800 dark:text-white mb-1 leading-tight group-hover:text-blue-600 transition-colors">{proker.title}</h3>
                        <p className="text-xs font-bold text-slate-500 mb-4">{proker.division}</p>

                        {/* Stats Grid */}
                        <div className="grid grid-cols-2 gap-3 mb-4">
                           <div className="bg-slate-50 dark:bg-white/5 p-2 rounded-lg border border-slate-100 dark:border-white/5">
                              <p className="text-[9px] text-slate-400 font-bold uppercase mb-0.5">Tanggal</p>
                              <p className="text-[10px] font-bold text-slate-700 dark:text-slate-200 flex items-center gap-1.5"><Calendar size={10}/> {proker.date}</p>
                           </div>
                           <div className="bg-slate-50 dark:bg-white/5 p-2 rounded-lg border border-slate-100 dark:border-white/5">
                              <p className="text-[9px] text-slate-400 font-bold uppercase mb-0.5">Anggaran</p>
                              <p className="text-[10px] font-bold text-slate-700 dark:text-slate-200">Rp {proker.budget.toLocaleString()}</p>
                           </div>
                        </div>
                     </div>

                     {/* Footer (Progress) */}
                     <div className="mt-auto">
                        <div className="flex justify-between items-end mb-1">
                           <p className="text-[10px] font-bold text-slate-500">Progress</p>
                           <p className="text-[10px] font-black text-blue-600">{proker.progress}%</p>
                        </div>
                        <div className="w-full h-2 bg-slate-100 dark:bg-white/10 rounded-full overflow-hidden">
                           <div 
                              className={`h-full rounded-full transition-all duration-1000 ease-out ${
                                 proker.progress === 100 ? 'bg-green-500' : 'bg-blue-600'
                              }`} 
                              style={{ width: `${proker.progress}%` }}
                           ></div>
                        </div>
                        <div className="mt-3 pt-3 border-t border-slate-100 dark:border-white/5 flex justify-between items-center">
                           <div className="flex items-center gap-2">
                              <div className="w-5 h-5 rounded-full bg-slate-200 dark:bg-white/20 flex items-center justify-center text-[9px] font-black text-slate-600 dark:text-white">
                                 {proker.pic.charAt(0)}
                              </div>
                              <span className="text-[10px] font-bold text-slate-500">{proker.pic}</span>
                           </div>
                           <button className="p-1.5 hover:bg-slate-100 dark:hover:bg-white/10 rounded-lg text-slate-400 transition-colors"><MoreVertical size={14}/></button>
                        </div>
                     </div>

                  </div>
               ))}
            </div>
         </div>

      </div>
    </div>
  );
}